<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { automationApi } from '@/api/automation'

const items = ref<any[]>([]), loading = ref(true), open = ref(false), saving = ref(false)
const form = reactive({ name: '', target_type: 'keyword', query: '', timezone: 'Asia/Shanghai', scheduleKind: 'daily', time: '09:00', minutes: 60, channels: ['in_app'] as string[], enabled: true })
async function load() { loading.value = true; try { items.value = await automationApi.subscriptions() } finally { loading.value = false } }
async function create() {
  saving.value = true
  try {
    const schedule = form.scheduleKind === 'interval' ? { kind: 'interval', minutes: form.minutes } : { kind: 'daily', time: form.time }
    await automationApi.createSubscription({ name: form.name, target_type: form.target_type, query: form.query, timezone: form.timezone, schedule, channels: form.channels, enabled: form.enabled, filters: {} })
    open.value = false; ElMessage.success('订阅及关联任务已创建'); await load()
  } finally { saving.value = false }
}
async function toggle(item: any) { item.enabled = !item.enabled; await automationApi.toggleSubscription(item.id, item.enabled); ElMessage.success(item.enabled ? '订阅已恢复' : '订阅已暂停') }
async function remove(item: any) { await ElMessageBox.confirm(`删除订阅“${item.name}”及关联任务？`, '删除订阅'); await automationApi.deleteSubscription(item.id); await load() }
function scheduleText(item: any) { return item.schedule.kind === 'interval' ? `每 ${item.schedule.minutes} 分钟` : `每天 ${item.schedule.time}` }
onMounted(load)
</script>

<template>
  <main class="subscription-page">
    <header class="page-head"><div><small>COLLECTIONS / SUBSCRIPTIONS</small><h1>订阅中心</h1><p>持续跟踪关键词、企业、行业和自动日报。</p></div><button @click="open=true"><el-icon><Plus /></el-icon>新建订阅</button></header>
    <section class="summary"><div><b>{{items.filter(i=>i.enabled).length}}</b><span>运行中</span></div><div><b>{{items.length}}</b><span>全部订阅</span></div><div><b>{{items.filter(i=>i.channels.includes('webhook')).length}}</b><span>外部投递</span></div></section>
    <section v-loading="loading" class="subscription-list">
      <article v-for="item in items" :key="item.id"><div class="target"><el-icon><Aim /></el-icon><span>{{item.target_type}}</span></div><div class="copy"><h2>{{item.name}}</h2><p>{{item.query || '自动报告'}} · {{scheduleText(item)}} · {{item.timezone}}</p><div><span v-for="channel in item.channels" :key="channel">{{channel}}</span></div></div><div class="state"><i :class="{on:item.enabled}"></i>{{item.enabled?'运行中':'已暂停'}}</div><div class="actions"><button :title="item.enabled?'暂停':'恢复'" @click="toggle(item)"><el-icon><VideoPause v-if="item.enabled"/><VideoPlay v-else/></el-icon></button><button title="删除" @click="remove(item)"><el-icon><Delete /></el-icon></button></div></article>
      <div v-if="!loading&&!items.length" class="empty"><el-icon><Bell /></el-icon><h2>还没有订阅</h2><p>创建后系统会按你的时区执行监控或生成日报。</p><button @click="open=true">新建订阅</button></div>
    </section>
    <div v-if="open" class="overlay" @click.self="open=false"><form @submit.prevent="create"><header><h2>新建订阅</h2><button type="button" @click="open=false"><el-icon><Close /></el-icon></button></header><label>名称<input v-model="form.name" maxlength="200" required placeholder="例如：OpenAI 每日动态"/></label><div class="grid"><label>对象类型<select v-model="form.target_type"><option value="keyword">关键词</option><option value="company">企业</option><option value="industry">行业</option><option value="report">自动日报</option></select></label><label>时区<select v-model="form.timezone"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option></select></label></div><label v-if="form.target_type!=='report'">查询词<input v-model="form.query" required placeholder="关键词或企业名称"/></label><div class="grid"><label>执行方式<select v-model="form.scheduleKind"><option value="daily">每天</option><option value="interval">固定间隔</option></select></label><label v-if="form.scheduleKind==='daily'">执行时间<input v-model="form.time" type="time"/></label><label v-else>间隔分钟<input v-model.number="form.minutes" type="number" min="5" max="1440"/></label></div><fieldset><legend>通知渠道</legend><label><input v-model="form.channels" type="checkbox" value="in_app"/>站内</label><label><input v-model="form.channels" type="checkbox" value="email"/>邮件</label><label><input v-model="form.channels" type="checkbox" value="webhook"/>Webhook（需确认）</label></fieldset><footer><button type="button" @click="open=false">取消</button><button class="primary" :disabled="saving">{{saving?'正在创建':'创建订阅'}}</button></footer></form></div>
  </main>
</template>

<style scoped>
.subscription-page{min-height:100vh;padding:36px clamp(18px,4vw,64px);color:#17231f;background:#f3f6f5}.page-head{display:flex;align-items:end;justify-content:space-between;padding-bottom:25px;border-bottom:1px solid #cad7d2}.page-head small{color:#167f76;font-weight:800}.page-head h1{margin:7px 0;font:650 40px Georgia,"Songti SC",serif}.page-head p{margin:0;color:#6b7d76}.page-head>button,.empty button,.primary{height:40px;padding:0 14px;border:0;border-radius:5px;color:#fff;background:#183129}.summary{margin:20px 0;display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #cdd9d4;border-radius:7px;background:#fff}.summary div{padding:18px;border-left:1px solid #dce4e1}.summary div:first-child{border:0}.summary b,.summary span{display:block}.summary b{font-size:25px}.summary span{color:#71827b;font-size:11px}.subscription-list{min-height:360px;border:1px solid #cdd9d4;border-radius:7px;background:#fff}.subscription-list article{min-height:94px;padding:15px;display:grid;grid-template-columns:90px 1fr 90px auto;gap:16px;align-items:center;border-top:1px solid #e0e7e4}.subscription-list article:first-child{border:0}.target{display:grid;gap:5px;color:#167f76;font-size:10px;text-transform:uppercase}.target .el-icon{font-size:22px}.copy h2{margin:0;font-size:17px}.copy p{margin:7px 0;color:#6e8079;font-size:11px}.copy div span{margin-right:5px;padding:3px 6px;border-radius:3px;color:#45665c;background:#eaf2ef;font-size:9px}.state{font-size:11px}.state i{width:7px;height:7px;margin-right:6px;border-radius:50%;display:inline-block;background:#a2ada9}.state i.on{background:#15926f}.actions{display:flex;gap:6px}.actions button{width:34px;height:34px;border:1px solid #ced9d5;border-radius:4px;background:#fff}.empty{min-height:360px;display:grid;place-items:center;align-content:center;text-align:center;color:#75877f}.empty>.el-icon{font-size:46px}.empty h2{margin:12px 0 0}.overlay{position:fixed;inset:0;z-index:600;display:grid;place-items:center;padding:16px;background:rgba(11,28,22,.44)}.overlay form{width:min(560px,100%);padding:23px;border-radius:7px;background:#fff}.overlay form>header,.overlay footer{display:flex;align-items:center;justify-content:space-between}.overlay h2{margin:0}.overlay header button{width:32px;height:32px;border:0;background:transparent}.overlay label{margin-top:15px;display:grid;gap:6px;color:#52675f;font-size:11px}.overlay input,.overlay select{height:40px;padding:0 9px;border:1px solid #c9d5d0;border-radius:4px;background:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}fieldset{margin-top:18px;border:1px solid #d2dcd8}fieldset label{display:inline-flex;margin:8px 16px 8px 0;align-items:center;gap:5px}fieldset input{height:auto}.overlay footer{margin-top:22px;justify-content:flex-end;gap:8px}.overlay footer button{height:38px;padding:0 14px;border:1px solid #cad6d1;border-radius:4px;background:#fff}.overlay footer .primary{border:0;background:#183129}@media(max-width:650px){.page-head h1{font-size:32px}.page-head p{display:none}.summary{grid-template-columns:1fr 1fr 1fr}.subscription-list article{grid-template-columns:60px 1fr auto}.state{grid-column:2}.actions{grid-column:3;grid-row:1}.grid{grid-template-columns:1fr}}
</style>
<style scoped>.overlay form{max-height:calc(100vh - 32px);overflow:auto}</style>
